const item = $input.item.json;
const callback = item.callback_query;
const msg = item.message;

let eventType = 'UNKNOWN';
let timePreset = 'all';
let statusPreset = 'all';
let chatId = null;
let messageId = null;
let fromUser = 'Usuario';
let callbackData = '';
let commandParam = '';
let querySql = '';
let replyText = '';

if (callback) {
  chatId = callback.message?.chat?.id;
  messageId = callback.message?.message_id;
  fromUser = callback.from?.username ? `@${callback.from.username}` : (callback.from?.first_name || 'Usuario');
  callbackData = callback.data || '';

  if (callbackData.startsWith('dosing_time:')) {
    eventType = 'DOSING_STATUS_MENU';
    timePreset = callbackData.replace('dosing_time:', '');
  } else if (callbackData.startsWith('dosing_query:')) {
    eventType = 'DOSING_QUERY';
    const parts = callbackData.replace('dosing_query:', '').split(':');
    timePreset = parts[0] || 'all';
    statusPreset = parts[1] || 'all';
  } else if (callbackData === 'filter_cmd:clean') {
    eventType = 'FILTER';
  } else if (callbackData === 'filter_cmd:status') {
    eventType = 'FILTER_STATUS';
  } else if (callbackData === 'filter_cmd:menu') {
    eventType = 'FILTER_MENU';
  } else if (callbackData.startsWith('filter_cleaned:')) {
    eventType = 'CALLBACK_ACTION';
    const notifId = callbackData.replace('filter_cleaned:', '');
    querySql = `INSERT INTO "FilterCleaningLog" (id, "cleanedAt", "nextDueAt", notes, "confirmedBy", source, "createdAt") VALUES (gen_random_uuid(), NOW(), (date_trunc('day', NOW() AT TIME ZONE 'America/Caracas') + INTERVAL '2 days' + INTERVAL '8 hours') AT TIME ZONE 'America/Caracas', 'Confirmado vía Telegram', '${fromUser}', 'TELEGRAM_BOT', NOW()); UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}' OR type = 'MAINTENANCE_REMINDER';`;
    replyText = `\u200B\n*Mantenimiento de Filtro de Agua Registrado*\n\n👤 Confirmado por: ${fromUser}\n📅 Limpieza realizada con éxito\n⏰ Próxima Notificación: dentro de 2 días a las 8:00 AM\n\nEl temporizador de mantenimiento ha sido reiniciado.`;
  } else if (callbackData.startsWith('dosing_manual_confirm:')) {
    eventType = 'CALLBACK_ACTION';
    const parts = callbackData.replace('dosing_manual_confirm:', '').split(':');
    const dosingLogId = parts[0];
    const notifId = parts[1] || '';
    const notifUpdate = notifId ? `UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}';` : '';
    querySql = `UPDATE "DosingLog" SET status = 'COMPLETED'::"TaskStatus", "executedAt" = NOW() WHERE id = '${dosingLogId}'; ${notifUpdate}`;
    replyText = `\u200B\n*Dosificación Manual Completada*\n\nMarcada como realizada por ${fromUser}`;
  } else if (callbackData.startsWith('agro_hw_confirm:')) {
    eventType = 'CALLBACK_ACTION';
    const parts = callbackData.replace('agro_hw_confirm:', '').split(':');
    const taskId = parts[0];
    const notifId = parts[1] || '';
    querySql = `UPDATE "TaskLog" SET status = 'AUTHORIZED'::"TaskStatus" WHERE id = '${taskId}'; UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}';`;
    replyText = `\u200B\n*Tanque Confirmado y Autorizado*\n\nConfirmado por ${fromUser}\nEl riego de agroquímicos se ejecutará a la hora programada.`;
  } else if (callbackData.startsWith('agro_hw_postpone:')) {
    eventType = 'CALLBACK_ACTION';
    const parts = callbackData.replace('agro_hw_postpone:', '').split(':');
    const taskId = parts[0];
    const hours = parseInt(parts[1] || '24', 10);
    const notifId = parts[2] || '';
    querySql = `UPDATE "TaskLog" SET "scheduledAt" = "scheduledAt" + INTERVAL '${hours} hours' WHERE id = '${taskId}'; UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}';`;
    replyText = `\u200B\n*Riego Pospuesto ${hours} Horas*\n\nPospuesto por ${fromUser}`;
  } else if (callbackData.startsWith('agro_hw_cancel:')) {
    eventType = 'CALLBACK_ACTION';
    const parts = callbackData.replace('agro_hw_cancel:', '').split(':');
    const taskId = parts[0];
    const notifId = parts[1] || '';
    querySql = `UPDATE "TaskLog" SET status = 'CANCELLED'::"TaskStatus" WHERE id = '${taskId}'; UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}';`;
    replyText = `\u200B\n*Riego Cancelado*\n\nCancelado por ${fromUser}`;
  } else if (callbackData.startsWith('confirm_')) {
    eventType = 'CALLBACK_ACTION';
    const taskId = callbackData.replace('confirm_', '');
    querySql = `UPDATE "DosingLog" SET status = 'COMPLETED'::"TaskStatus", "executedAt" = NOW() WHERE id = '${taskId}';`;
    replyText = `\u200B\n*Tarea Confirmada*\n\nRegistrada por ${fromUser}`;
  } else if (callbackData.startsWith('cancel_')) {
    eventType = 'CALLBACK_ACTION';
    const taskId = callbackData.replace('cancel_', '');
    querySql = `UPDATE "DosingLog" SET status = 'CANCELLED'::"TaskStatus" WHERE id = '${taskId}';`;
    replyText = `\u200B\n*Tarea Cancelada*\n\nPor ${fromUser}`;
  }
} else if (msg && msg.text) {
  chatId = msg.chat?.id;
  messageId = msg.message_id;
  fromUser = msg.from?.username ? `@${msg.from.username}` : (msg.from?.first_name || 'Usuario');
  const text = msg.text.trim();
  const parts = text.split(' ');
  const cmd = parts[0].toLowerCase().split('@')[0];
  const subCmd = (parts[1] || '').toLowerCase();
  commandParam = parts.slice(1).join(' ').trim();

  if (cmd === '/status') {
    eventType = 'STATUS';
  } else if (cmd === '/dosing' || cmd === '/dosificacion') {
    eventType = 'DOSING_TIME_MENU';
  } else if (cmd === '/complete' || cmd === '/completar') {
    eventType = 'COMPLETE';
  } else if (cmd === '/filterstatus' || (cmd === '/filter' && (subCmd === 'status' || subCmd === 'estado'))) {
    eventType = 'FILTER_STATUS';
  } else if (cmd === '/filterclean' || (cmd === '/filter' && (subCmd === 'clean' || subCmd === 'limpiar'))) {
    eventType = 'FILTER';
  } else if (cmd === '/filter' || cmd === '/filtro') {
    eventType = 'FILTER_MENU';
  } else if (cmd === '/help' || cmd === '/start') {
    eventType = 'HELP';
  }
}

return [{
  json: {
    eventType,
    chatId,
    messageId,
    fromUser,
    callbackData,
    timePreset,
    statusPreset,
    commandParam,
    querySql,
    replyText
  }
}];

const chatId = $('Parsear Evento').first().json.chatId;
const items = $input.all();
const ema = items.find(i => i.json.name === 'Weather_Station_ZONA_A')?.json || {};
const actuador = items.find(i => i.json.name === 'Actuator_Controller')?.json || {};

const formatStatus = (s) => {
  if (!s) return 'Offline';
  const upper = String(s).toUpperCase();
  if (upper === 'ONLINE' || upper === 'REBOOT') return 'Online';
  if (upper === 'SLEEP') return 'Sleep';
  return 'Offline';
};

const replyText = `\u200B\n*Estado de Infraestructura*\n\n` +
  `Nodo EMA: ${formatStatus(ema.status)}\n` +
  `Nodo Actuador: ${formatStatus(actuador.status)}`;

return [{ json: { chatId, replyText } }];

