const event = $('Parsear Evento').first().json;
const items = $input.all();
const ZONE_LABELS = { ZONA_A: 'Orquideario', ZONA_B: 'Jardín', ZONA_C: 'Terraza', ZONA_D: 'Ventanas', EXTERIOR: 'Exterior' };
const STATUS_LABELS = {
  PENDING: 'Pendiente',
  WAITING_CONFIRMATION: 'Esperando',
  COMPLETED: 'Completada',
  CANCELLED: 'Cancelada',
  EXPIRED: 'Expirada',
  AUTHORIZED: 'Autorizada'
};
const timeMap = { 'today': 'Hoy', 'week': 'Esta Semana', 'next-week': 'Prox. Semana', 'month': 'Este Mes', 'next-month': 'Prox. Mes', 'all': 'Todos los Tiempos' };
const statusMap = { 'PENDING': 'Pendientes', 'COMPLETED': 'Completadas', 'CANCELLED': 'Canceladas', 'all': 'Todos los Estados' };

const timeLabel = timeMap[event.timePreset] || 'Todos los Tiempos';
const statusLabel = statusMap[event.statusPreset] || 'Todos los Estados';

function getCaracasDateParts(d) {
  if (!d) return { dia: 'N/A', fecha: 'N/A', hora: 'N/A' };
  const diaRaw = d.toLocaleDateString('es-VE', { weekday: 'long', timeZone: 'America/Caracas' });
  const dia = diaRaw.charAt(0).toUpperCase() + diaRaw.slice(1);
  const fecha = d.toLocaleDateString('es-VE', { day: 'numeric', month: 'long', timeZone: 'America/Caracas' });
  let horaStr = d.toLocaleTimeString('es-VE', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'America/Caracas' });
  const hora = horaStr.replace(/[\.\s]*([ap])\.?\s*m\.?/i, ' $1m').toLowerCase().trim();
  return { dia, fecha, hora };
}

function formatZonesVertical(zones) {
  if (!zones) return 'Zona: General\n';
  let arr = Array.isArray(zones) ? zones : [zones];
  if (typeof zones === 'string' && zones.startsWith('{')) {
    arr = zones.replace(/[{}]/g, '').split(',');
  }
  return arr.map(z => `Zona: ${ZONE_LABELS[z.trim()] || z.trim()}`).join('\n') + '\n';
}

function formatDosingTaskBlock(row) {
  const agroName = row.agrochemical_name || row.agrochemicalName || row.program_name || row.programName || row.schedule_name || 'Dosificación';
  const statusStr = STATUS_LABELS[row.status] || row.status;
  const dateObj = new Date(row.scheduledAt);
  const { dia, fecha, hora } = getCaracasDateParts(dateObj);
  const zonesStr = formatZonesVertical(row.zones);

  let doseSection = '';
  const ingredients = typeof row.ingredients === 'string' ? JSON.parse(row.ingredients) : (row.ingredients || []);
  if (row.isMix && Array.isArray(ingredients) && ingredients.length > 0) {
    ingredients.forEach(ing => {
      doseSection += `Insumo: ${ing.name}\n`;
      if (ing.dosageValue && ing.dosageUnit) {
        doseSection += `Dosis: (${ing.dosageValue} ${ing.dosageUnit})\n`;
      } else {
        doseSection += `Dosis: Sin especificación\n`;
      }
    });
  } else {
    const unit = row.agrochemical_unit || row.agrochemicalUnit;
    if (row.dosageValue && unit) {
      doseSection += `Dosis: (${row.dosageValue} ${unit})\n`;
    } else {
      doseSection += `Dosis: Sin especificación\n`;
    }
  }

  let block = `<b>${agroName}</b>\n`;
  block += `Estado: ${statusStr}\n`;
  block += doseSection;
  block += zonesStr;
  block += `Hora: ${hora}\n`;
  block += `Día: ${dia}\n`;
  block += `Fecha: ${fecha}\n\n`;
  return block;
}

if (items.length === 0 || !items[0].json.id) {
  return [{
    json: {
      chatId: event.chatId,
      messageId: event.messageId,
      replyText: `<b>Tareas de Dosificación</b>\n${timeLabel}\n${statusLabel}\n\nSin tareas registradas` 
    }
  }];
}

let replyText = `<b>Tareas de Dosificación</b>\n${timeLabel}\n${statusLabel}\n\n`;

items.forEach((item) => {
  replyText += formatDosingTaskBlock(item.json);
});

return [{
  json: {
    chatId: event.chatId,
    messageId: event.messageId,
    replyText: replyText.trimEnd()
  }
}];

