      replyMarkupObj: {
        inline_keyboard: [
          [
            {
              text: '📊 Ver Tareas de Dosificación',
              callback_data: 'dosing_time:all'
            }
          ]
        ]
      }
    }
  }];
}

let replyText = `<b>Dosificación Manual</b>\n\nSelecciona la tarea que deseas marcar como completada:\n\n`;
const inline_keyboard = [];

items.forEach((item) => {
  const row = item.json;
  const agroName = row.agrochemical_name || row.program_name || row.schedule_name || 'Dosificación';
  replyText += formatDosingTaskBlock(row);

  inline_keyboard.push([
    {
      text: `✅ ${agroName.substring(0, 36)}`,
      callback_data: `dosing_manual_confirm:${row.id}:`
    }
  ]);
});

return [{
  json: {
    chatId: event.chatId,
    replyText: replyText.trimEnd(),
    replyMarkupObj: {
      inline_keyboard
    }
  }
}];

const event = $('Parsear Evento').first().json;
const now = new Date();

function formatDateTimeCaracas(d) {
  if (!d) return 'N/A';
  const str = d.toLocaleString('es-VE', {
    timeZone: 'America/Caracas',
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  });
  return str.charAt(0).toUpperCase() + str.slice(1).replace(/\s[ap]\.\s?m\./i, m => m.includes('p') ? ' pm' : ' am');
}

// 2 días en el futuro fijado a las 8:00 AM Caracas (UTC-4 = 12:00 UTC)
const caracasDateStr = now.toLocaleDateString('en-CA', { timeZone: 'America/Caracas' });
const [year, month, day] = caracasDateStr.split('-').map(Number);
const nextDue = new Date(Date.UTC(year, month - 1, day + 2, 12, 0, 0));

const replyText = `\u200B\n*Mantenimiento de Filtro de Agua Registrado*\n\n` +
  `👤 Registrado por: ${event.fromUser}\n` +
  `📅 Fecha de Limpieza: ${formatDateTimeCaracas(now)}\n` +
  `⏰ Próxima Notificación: ${formatDateTimeCaracas(nextDue)}\n\n` +
  `El temporizador de mantenimiento ha sido reiniciado.`;

return [{
  json: {
    chatId: event.chatId,
    replyText
  }
}];

