    }
  }];
}

const row = items[0].json;
const cleanedDate = new Date(row.cleanedAt);
const dueDate = new Date(row.nextDueAt);
const now = new Date();
const isOverdue = now >= dueDate;

const replyText = `\u200B\n*Estado del Filtro de Agua*\n\n` +
  `📊 Condición: ${isOverdue ? '⚠️ *Vencido (Requiere Limpieza)*' : '✅ *Al día (Operativo)*'}\n` +
